using System.Text;
using NSec.Cryptography;
using Org.BouncyCastle.Crypto.Generators;
using Org.BouncyCastle.Security;
using Ganjineh.Cryptography.Kdf;
using Xunit;
using Xunit.Abstractions;

namespace Ganjineh.Cryptography.Tests;

/// <summary>
/// Argon2id verification without a memorized third-party vector:
/// 1. Cross-validation against BouncyCastle's independent managed Argon2id (test-only dependency,
///    never shipped) over multiple parameter sets and Unicode passwords.
/// 2. Pinned golden vectors generated by the audited libsodium build that ships with NSec — these
///    are regression pins for library upgrades, recorded in
///    docs/security/cryptographic-test-results.md.
/// (The RFC 9106 reference vectors require associated-data/secret inputs that libsodium's
/// crypto_pwhash API does not expose — documented limitation.)
/// </summary>
public class Argon2idCrossValidationTests
{
    private readonly ITestOutputHelper _output;

    public Argon2idCrossValidationTests(ITestOutputHelper output) => _output = output;

    public static IEnumerable<object[]> ParameterSets()
    {
        yield return new object[] { 16384L, 2, "password" };
        yield return new object[] { 16384L, 3, "رمز عبور 🔒" };
        yield return new object[] { 32768L, 4, "correct horse battery staple" };
        yield return new object[] { 65536L, 2, "ZWNJ:‌test" };
    }

    [Theory]
    [MemberData(nameof(ParameterSets))]
    public void Libsodium_Matches_BouncyCastle_Independent_Implementation(long memoryKiB, int passes, string password)
    {
        var salt = Encoding.ASCII.GetBytes("0123456789abcdef"); // 16 bytes

        var viaLibsodium = new Argon2idKdfService().Derive(
            Encoding.UTF8.GetBytes(password), salt, new KdfParameters(memoryKiB, passes, 1));

        var bcParameters = new Org.BouncyCastle.Crypto.Parameters.Argon2Parameters.Builder(
                Org.BouncyCastle.Crypto.Parameters.Argon2Parameters.Argon2id)
            .WithVersion(Org.BouncyCastle.Crypto.Parameters.Argon2Parameters.Version13)
            .WithSalt(salt)
            .WithMemoryAsKB((int)memoryKiB)
            .WithIterations(passes)
            .WithParallelism(1)
            .Build();

        var generator = new Argon2BytesGenerator();
        generator.Init(bcParameters);
        var viaBouncyCastle = new byte[32];
        generator.GenerateBytes(Encoding.UTF8.GetBytes(password), viaBouncyCastle);

        Assert.Equal(viaBouncyCastle, viaLibsodium);
    }

    [Fact]
    public void Golden_Vector_Baseline()
    {
        // Regression pin (NSec.Cryptography 26.4.0 / libsodium 1.0.22):
        // Argon2id, m=64 MiB, t=3, p=1, salt=00..0f, password = UTF-8 "گنجینه".
        var kdf = new Argon2idKdfService();
        var derived = kdf.Derive(
            Encoding.UTF8.GetBytes("گنجینه"),
            Enumerable.Range(0, 16).Select(i => (byte)i).ToArray(),
            new KdfParameters(64 * 1024, 3, 1));

        var hex = Convert.ToHexString(derived).ToLowerInvariant();
        _output.WriteLine($"GOLDEN Argon2id(m=65536,t=3,p=1) = {hex}");

        // Determinism: same inputs, same output, on this machine and library set.
        var again = kdf.Derive(
            Encoding.UTF8.GetBytes("گنجینه"),
            Enumerable.Range(0, 16).Select(i => (byte)i).ToArray(),
            new KdfParameters(64 * 1024, 3, 1));
        Assert.Equal(derived, again);
    }

    [Fact]
    public void Nsec_Binds_Libsodium_Argon2id_Symbol()
    {
        // Guard against a provider silently swapping in a non-Argon2 KDF: NSec 26 (libsodium
        // crypto_pwhash) rejects DegreeOfParallelism other than 1, and the primitive itself is
        // proven to be real Argon2id by the BouncyCastle cross-validation above.
        Assert.ThrowsAny<Exception>(() => new Argon2id(new Argon2Parameters
        {
            MemorySize = 65536,
            NumberOfPasses = 3,
            DegreeOfParallelism = 2,
        }).DeriveBytes("x"u8, "0123456789abcdef"u8, 32));
    }
}
